func TestEnumWebhookEventDeliveryStatus(t *testing.T) {
	t.Run("NewFromString_PENDING", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventDeliveryStatusFromString("PENDING")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEventDeliveryStatus("PENDING"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_DELIVERED", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventDeliveryStatusFromString("DELIVERED")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEventDeliveryStatus("DELIVERED"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_FAILED", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventDeliveryStatusFromString("FAILED")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEventDeliveryStatus("FAILED"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewWebhookEventDeliveryStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewWebhookEventDeliveryStatusFromString("PENDING")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

